import{_ as p,a0 as o,w as l,s as m,ao as n,I as r,a1 as t,A as a,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"在 Linux 下使用 RAID（七）：在 Raid 中扩展现有的 RAID 阵列和删除故障的磁盘 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（七）：在 Raid 中扩展现有的 RAID 阵列和删除故障的磁盘 | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（七）：在 Raid 中扩展现有的 RAID 阵列和删除故障的磁盘 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（七）：在 Raid 中扩展现有的 RAID 阵列和删除故障的磁盘 | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 7 - Growing an Existing RAID Array and Removing Failed Disks in Raid","title":"在 Linux 下使用 RAID（七）：在 Raid 中扩展现有的 RAID 阵列和删除故障的磁盘","tag":"RAID","desc":""},"relativePath":"RAID/Part 7 - Growing an Existing RAID Array and Removing Failed Disks in Raid.md","filePath":"[post].md"}'),s={name:"RAID/Part 7 - Growing an Existing RAID Array and Removing Failed Disks in Raid.md"};function R(c,d,A,w,D,g){const e=o("Link");return l(),m("div",null,[d[15]||(d[15]=n('<h1 id="在-linux-下使用-raid-七-在-raid-中扩展现有的-raid-阵列和删除故障的磁盘" tabindex="-1">在 Linux 下使用 RAID（七）：在 Raid 中扩展现有的 RAID 阵列和删除故障的磁盘 <a class="header-anchor" href="#在-linux-下使用-raid-七-在-raid-中扩展现有的-raid-阵列和删除故障的磁盘" aria-label="Permalink to “在 Linux 下使用 RAID（七）：在 Raid 中扩展现有的 RAID 阵列和删除故障的磁盘”">​</a></h1><p>每个新手都会对阵列（array）这个词所代表的意思产生疑惑。阵列只是磁盘的一个集合。换句话说，我们可以称阵列为一个集合（set）或一组（group）。就像一组鸡蛋中包含6个一样。同样 RAID 阵列中包含着多个磁盘，可能是2，4，6，8，12，16等，希望你现在知道了什么是阵列。</p><p>在这里，我们将看到如何扩展现有的阵列或 RAID 组。例如，如果我们在阵列中使用2个磁盘形成一个 raid 1 集合，在某些情况，如果该组中需要更多的空间，就可以使用 mdadm -grow 命令来扩展阵列大小，只需要将一个磁盘加入到现有的阵列中即可。在说完扩展（添加磁盘到现有的阵列中）后，我们将看看如何从阵列中删除故障的磁盘。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Growing-Raid-Array.jpg" alt="Grow Raid Array in Linux"></p><p><em>扩展 RAID 阵列和删除故障的磁盘</em></p><p>假设磁盘中的一个有问题了需要删除该磁盘，但我们需要在删除磁盘前添加一个备用磁盘来扩展该镜像，因为我们需要保存我们的数据。当磁盘发生故障时我们需要从阵列中删除它，这是这个主题中我们将要学习到的。</p><h4 id="扩展-raid-的特性" tabindex="-1">扩展 RAID 的特性 <a class="header-anchor" href="#扩展-raid-的特性" aria-label="Permalink to “扩展 RAID 的特性”">​</a></h4><ul><li>我们可以增加（扩展）任意 RAID 集合的大小。</li><li>我们可以在使用新磁盘扩展 RAID 阵列后删除故障的磁盘。</li><li>我们可以扩展 RAID 阵列而无需停机。</li></ul><p>####要求 ####</p><ul><li>为了扩展一个RAID阵列，我们需要一个已有的 RAID 组（阵列）。</li><li>我们需要额外的磁盘来扩展阵列。</li><li>在这里，我们使用一块磁盘来扩展现有的阵列。</li></ul><p>在我们了解扩展和恢复阵列前，我们必须了解有关 RAID 级别和设置的基本知识。点击下面的链接了解这些。</p>',11)),r("ul",null,[r("li",null,[t(e,{href:"https://linux.cn/article-6085-1.html"},{default:a(()=>[...d[0]||(d[0]=[i("介绍 RAID 的级别和概念",-1)])]),_:1})]),r("li",null,[t(e,{href:"https://linux.cn/article-6087-1.html"},{default:a(()=>[...d[1]||(d[1]=[i("使用 mdadm 工具创建软件 RAID 0 （条带化）",-1)])]),_:1})])]),d[16]||(d[16]=n(`<h4 id="我的服务器设置" tabindex="-1">我的服务器设置 <a class="header-anchor" href="#我的服务器设置" aria-label="Permalink to “我的服务器设置”">​</a></h4><pre><code>操作系统 	:	CentOS 6.5 Final
 IP地址	 	:	192.168.0.230
 主机名		:	grow.tecmintlocal.com
2 块现有磁盘 	:	1 GB
1 块额外磁盘	:	1 GB
</code></pre><p>在这里，我们已有一个 RAID ，有2块磁盘，每个大小为1GB，我们现在再增加一个磁盘到我们现有的 RAID 阵列中，其大小为1GB。</p><h3 id="扩展现有的-raid-阵列" tabindex="-1">扩展现有的 RAID 阵列 <a class="header-anchor" href="#扩展现有的-raid-阵列" aria-label="Permalink to “扩展现有的 RAID 阵列”">​</a></h3><p>1、 在扩展阵列前，首先使用下面的命令列出现有的 RAID 阵列。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Existing-Raid-Array.png" alt="Check Existing Raid Array"></p><p><em>检查现有的 RAID 阵列</em></p><p><strong>注意</strong>: 以上输出显示，已经有了两个磁盘在 RAID 阵列中，级别为 RAID 1。现在我们增加一个磁盘到现有的阵列里。</p><p>2、 现在让我们添加新的磁盘“sdd”，并使用<code>fdisk</code>命令来创建分区。</p><pre><code># fdisk /dev/sdd
</code></pre><p>请使用以下步骤为 /dev/sdd 创建一个新的分区。</p><ul><li>按 <code>n</code> 创建新的分区。</li><li>然后按 <code>P</code> 选择主分区。</li><li>接下来选择分区号为1。</li><li>只需按两次回车键选择默认值即可。</li><li>然后，按 <code>P</code> 来打印创建好的分区。</li><li>按 <code>L</code>，列出所有可用的类型。</li><li>按 <code>t</code> 去修改分区。</li><li>键入 <code>fd</code> 设置为 Linux 的 RAID 类型，然后按回车确认。</li><li>然后再次使用<code>p</code>查看我们所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-New-sdd-Partition.png" alt="Create New Partition in Linux"></p><p><em>为 sdd 创建新的分区</em></p><p>3、 一旦新的 sdd 分区创建完成后，你可以使用下面的命令验证它。</p><pre><code># ls -l /dev/ | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Confirm-sdd-Partition.png" alt="Confirm sdd Partition"></p><p><em>确认 sdd 分区</em></p><p>4、 接下来，在添加到阵列前先检查磁盘是否有 RAID 分区。</p><pre><code># mdadm --examine /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-on-sdd-Partition.png" alt="Check Raid on sdd Partition"></p><p><em>在 sdd 分区中检查 RAID</em></p><p><strong>注意</strong>:以上输出显示，该盘有没有发现 super-blocks，意味着我们可以将新的磁盘添加到现有阵列。</p><p>5、 要添加新的分区 /dev/sdd1 到现有的阵列 md0，请使用以下命令。</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Add-Disk-To-Raid-Array.png" alt="Add Disk To Raid-Array"></p><p><em>添加磁盘到 RAID 阵列</em></p><p>6、 一旦新的磁盘被添加后，在我们的阵列中检查新添加的磁盘。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Confirm-Disk-Added-To-Raid.png" alt="Confirm Disk Added to Raid"></p><p><em>确认将新磁盘添加到 RAID 中</em></p><p><strong>注意</strong>: 在上面的输出，你可以看到磁盘已经被添加作为备用的。在这里，我们的阵列中已经有了2个磁盘，但我们期待阵列中有3个磁盘，因此我们需要扩展阵列。</p><p>7、 要扩展阵列，我们需要使用下面的命令。</p><pre><code># mdadm --grow --raid-devices=3 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Grow-Raid-Array.png" alt="Grow Raid Array"></p><p><em>扩展 Raid 阵列</em></p><p>现在我们可以看到第三块磁盘(sdd1)已被添加到阵列中，在第三块磁盘被添加后，它将从另外两块磁盘上同步数据。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Confirm-Raid-Array.png" alt="Confirm Raid Array"></p><p><em>确认 Raid 阵列</em></p><p><strong>注意</strong>: 对于大容量磁盘会需要几个小时来同步数据。在这里，我们使用的是1GB的虚拟磁盘，所以它非常快在几秒钟内便会完成。</p><h3 id="从阵列中删除磁盘" tabindex="-1">从阵列中删除磁盘 <a class="header-anchor" href="#从阵列中删除磁盘" aria-label="Permalink to “从阵列中删除磁盘”">​</a></h3><p>8、 在数据被从其他两个磁盘同步到新磁盘<code>sdd1</code>后，现在三个磁盘中的数据已经相同了（镜像）。</p><p>正如我前面所说的，假定一个磁盘出问题了需要被删除。所以，现在假设磁盘<code>sdc1</code>出问题了，需要从现有阵列中删除。</p><p>在删除磁盘前我们要将其标记为失效，然后我们才可以将其删除。</p><pre><code># mdadm --fail /dev/md0 /dev/sdc1
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Disk-Fail-in-Raid-Array.png" alt="Disk Fail in Raid Array"></p><p><em>在 RAID 阵列中模拟磁盘故障</em></p><p>从上面的输出中，我们清楚地看到，磁盘在下面被标记为 faulty。即使它是 faulty 的，我们仍然可以看到 raid 设备有3个，1个损坏了，状态是 degraded。</p><p>现在我们要从阵列中删除 faulty 的磁盘，raid 设备将像之前一样继续有2个设备。</p><pre><code># mdadm --remove /dev/md0 /dev/sdc1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Remove-Disk-in-Raid-Array.png" alt="Remove Disk in Raid Array"></p><p><em>在 Raid 阵列中删除磁盘</em></p><p>9、 一旦故障的磁盘被删除，然后我们只能使用2个磁盘来扩展 raid 阵列了。</p><pre><code># mdadm --grow --raid-devices=2 /dev/md0
# mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Grow-Disks-in-Raid-Array.png" alt="Grow Disks in Raid Array"></p><p><em>在 RAID 阵列扩展磁盘</em></p><p>从上面的输出中可以看到，我们的阵列中仅有2台设备。如果你需要再次扩展阵列，按照如上所述的同样步骤进行。如果你需要添加一个磁盘作为备用，将其标记为 spare，因此，如果磁盘出现故障时，它会自动顶上去并重建数据。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>在这篇文章中，我们已经看到了如何扩展现有的 RAID 集合，以及如何在重新同步已有磁盘的数据后从一个阵列中删除故障磁盘。所有这些步骤都可以不用停机来完成。在数据同步期间，系统用户，文件和应用程序不会受到任何影响。</p><p>在接下来的文章我将告诉你如何管理 RAID，敬请关注更新，不要忘了写评论。</p><hr>`,63)),r("p",null,[d[3]||(d[3]=i("via: ",-1)),t(e,{href:"http://www.tecmint.com/grow-raid-array-in-linux/"},{default:a(()=>[...d[2]||(d[2]=[i("http://www.tecmint.com/grow-raid-array-in-linux/",-1)])]),_:1})]),r("p",null,[d[7]||(d[7]=i("作者：",-1)),t(e,{href:"http://www.tecmint.com/author/babinlonston/"},{default:a(()=>[...d[4]||(d[4]=[i("Babin Lonston",-1)])]),_:1}),d[8]||(d[8]=i(" 译者：",-1)),t(e,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...d[5]||(d[5]=[i("strugglingyouth",-1)])]),_:1}),d[9]||(d[9]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...d[6]||(d[6]=[i("wxy",-1)])]),_:1})]),r("p",null,[d[12]||(d[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...d[10]||(d[10]=[i("LCTT",-1)])]),_:1}),d[13]||(d[13]=i(" 原创翻译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...d[11]||(d[11]=[i("Linux中国",-1)])]),_:1}),d[14]||(d[14]=i(" 荣誉推出",-1))])])}const h=p(s,[["render",R]]);export{f as __pageData,h as default};
